// Prepare array to collect all weather checks
const locations = $input.all();
const results = [];

for (const item of locations) {
  const location = item.json;
  results.push({
    json: {
      ward_name: location.ward_name,
      district_name: location.district_name,
      latitude: location.latitude,
      longitude: location.longitude,
      farm_count: location.farm_count,
      farmer_count: location.farmer_count
    }
  });
}

return results;

const location = $input.item.json;
const forecast = $input.item.json;

// Analyze next 24 hours (8 intervals x 3 hours)
const forecasts = forecast.list ? forecast.list.slice(0, 8) : [];

let hasRain = false;
let hasStorm = false;
let hasHeavyRain = false;
let maxRain = 0;
let maxWind = 0;
let alerts = [];

for (const item of forecasts) {
  const weather = item.weather[0];
  const rain = item.rain ? item.rain['3h'] || 0 : 0;
  const wind = item.wind ? item.wind.speed || 0 : 0;

  // Check for rain (id 5xx)
  if (weather.id >= 500 && weather.id < 600) {
    hasRain = true;
    if (rain > maxRain) maxRain = rain;

    // Heavy rain: > 7mm/3h
    if (rain > 7) {
      hasHeavyRain = true;
    }
  }

  // Check for thunderstorm (id 2xx)
  if (weather.id >= 200 && weather.id < 300) {
    hasStorm = true;
  }

  // Check for strong wind (> 10 m/s = 36 km/h)
  if (wind > 10) {
    if (wind > maxWind) maxWind = wind;
  }
}

// Determine severity and create alert message
let severity = 'low';
let alertType = 'weather';
let title = '';
let message = '';

if (hasStorm || hasHeavyRain || maxWind > 15) {
  severity = 'high';

  if (hasStorm) {
    alertType = 'storm';
    title = `⚠️ CẢNH BÁO BÃO - ${location.ward_name}, ${location.district_name}`;
    message = `Dự báo có dông/bão trong 24h tới.`;
  } else if (hasHeavyRain) {
    alertType = 'heavy_rain';
    title = `🌧️ CẢNH BÁO MƯA LỚN - ${location.ward_name}, ${location.district_name}`;
    message = `Dự báo mưa lớn ${maxRain.toFixed(1)}mm/3h trong 24h tới.`;
  } else if (maxWind > 15) {
    alertType = 'strong_wind';
    title = `💨 CẢNH BÁO GIÓ MẠNH - ${location.ward_name}, ${location.district_name}`;
    message = `Dự báo gió mạnh ${maxWind.toFixed(1)} m/s (${(maxWind * 3.6).toFixed(0)} km/h).`;
  }

  message += `\n\n📍 Khu vực: ${location.ward_name}, ${location.district_name}`;
  message += `\n🏡 Ảnh hưởng: ${location.farm_count} trang trại, ${location.farmer_count} nông dân`;
  message += `\n\n⚠️ Khuyến cáo:`;

  if (hasStorm) {
    message += `\n- Gia cố nhà kính, lưới che`;
    message += `\n- Thoát nước cho ruộng`;
    message += `\n- Không sử dụng thuốc BVTV`;
  } else if (hasHeavyRain) {
    message += `\n- Kiểm tra hệ thống thoát nước`;
    message += `\n- Không tưới cây`;
    message += `\n- Che chắn cho cây non`;
  } else if (maxWind > 15) {
    message += `\n- Chằng chống giàn leo`;
    message += `\n- Gia cố lưới che`;
    message += `\n- Thu hoạch sớm nếu gần đến kỳ`;
  }

} else if (hasRain) {
  severity = 'medium';
  alertType = 'rain';
  title = `🌦️ Thông báo thời tiết - ${location.ward_name}, ${location.district_name}`;
  message = `Dự báo có mưa trong 24h tới.`;
  message += `\n📍 Khu vực: ${location.ward_name}, ${location.district_name}`;
  message += `\n💡 Lưu ý: Điều chỉnh lịch tưới cây và phun thuốc.`;
}

// Return result
if (title) {
  const now = new Date();
  const validUntil = new Date(now.getTime() + 24 * 60 * 60 * 1000); // +24h

  return {
    json: {
      should_alert: true,
      alert_type: alertType,
      severity: severity,
      title: title,
      message: message,
      ward_name: location.ward_name,
      district_name: location.district_name,
      valid_from: now.toISOString(),
      valid_until: validUntil.toISOString(),
      is_active: true,
      max_rain: maxRain,
      max_wind: maxWind,
      farm_count: location.farm_count,
      farmer_count: location.farmer_count
    }
  };
} else {
  return {
    json: {
      should_alert: false,
      ward_name: location.ward_name,
      message: 'Thời tiết bình thường'
    }
  };
}

const alertData = $node["Analyze Weather"].json;
const alertId = $node["Create Alert"].json.id;
const notifications = $input.all();

return {
  json: {
    success: true,
    alert_id: alertId,
    alert_type: alertData.alert_type,
    severity: alertData.severity,
    location: `${alertData.ward_name}, ${alertData.district_name}`,
    affected_farms: alertData.farm_count,
    affected_farmers: alertData.farmer_count,
    notifications_sent: notifications.length,
    message: alertData.title,
    timestamp: new Date().toISOString()
  }
};

const location = $input.item.json;
return {
  json: {
    skipped: true,
    location: `${location.ward_name}`,
    reason: location.message || 'No severe weather',
    timestamp: new Date().toISOString()
  }
};
